namespace sv_5fe4cacb318c4591891fbcc3744e2c48.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_5fe4cacb318c4591891fbcc3744e2c48.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => _activeSection = section">
                    <span class="nav-icon">@GetSectionIcon(section)</span>
                    <span>@section</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (_activeSection == "Profile") { @RenderProfile }
            else if (_activeSection == "Notifications") { @RenderNotifications }
            else if (_activeSection == "Security") { @RenderSecurity }
            else if (_activeSection == "Appearance") { @RenderAppearance }
        }
    </div>
</div>

@* Toast notification *@
@if (_toastVisible)
{
    <div class="settings-toast @(_toastIsError ? "toast-error" : "")">
        @_toastMessage
    </div>
}

@* Session revoke confirmation dialog *@
@if (_showRevokeDialog)
{
    <div class="modal-backdrop" @onclick="() => _showRevokeDialog = false"></div>
    <div class="confirm-dialog">
        <h6>Revoke Session</h6>
        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
        <div class="dialog-actions">
            <button class="btn btn-secondary btn-sm" @onclick="() => _showRevokeDialog = false">Cancel</button>
            <button class="btn btn-danger btn-sm" @onclick="ConfirmRevokeSession">Revoke</button>
        </div>
    </div>
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile
    private UserProfile? _profile;
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private bool _editEmailNotif;
    private bool _editPushNotif;
    private bool _editWeeklyDigest;
    private List<string> _allChannels = ["general", "announcements", "engineering", "design", "marketing", "support"];
    private HashSet<string> _mutedChannels = new();

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = "session-1"; // Simulated current session

    // Appearance
    private AppearanceSettings? _appearanceSettings;
    private string _editTheme = "System";
    private string _editFontSize = "Medium";
    private string _editLanguage = "en";
    private bool _editCompactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Spanish",
        ["fr"] = "French",
        ["de"] = "German",
        ["ja"] = "Japanese",
        ["zh"] = "Chinese",
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _savedProfile = _profile;
        ResetProfileFields();

        _notificationPrefs = notifTask.Result;
        ResetNotificationFields();

        _securitySettings = securityTask.Result;

        _appearanceSettings = appearanceTask.Result;
        ResetAppearanceFields();
    }

    // ---------- Profile ----------

    private void ResetProfileFields()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editBio = _profile.Bio;
        _editAvatarUrl = _profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _savedProfile = updated;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        _profile = _savedProfile;
        ResetProfileFields();
    }

    private bool ProfileHasChanges =>
        _profile is not null &&
        (_editDisplayName != _savedProfile?.DisplayName ||
         _editEmail != _savedProfile?.Email ||
         _editBio != _savedProfile?.Bio ||
         _editAvatarUrl != _savedProfile?.AvatarUrl);

    // ---------- Notifications ----------

    private void ResetNotificationFields()
    {
        if (_notificationPrefs is null) return;
        _editEmailNotif = _notificationPrefs.EmailNotifications;
        _editPushNotif = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_notificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editEmailNotif, _editPushNotif, _editWeeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        await ShowToast("Notification preferences saved.");
    }

    // ---------- Security ----------

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", isError: true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", isError: true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("Password must be at least 8 characters.", isError: true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // ---------- Appearance ----------

    private void ResetAppearanceFields()
    {
        if (_appearanceSettings is null) return;
        _editTheme = _appearanceSettings.Theme;
        _editFontSize = _appearanceSettings.FontSize;
        _editLanguage = _appearanceSettings.Language;
        _editCompactMode = _appearanceSettings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearanceSettings = updated;
        await ShowToast("Appearance settings saved.");
    }

    private string PreviewFontClass => _editFontSize switch
    {
        "Small" => "preview-font-small",
        "Large" => "preview-font-large",
        _ => "preview-font-medium"
    };

    // ---------- Helpers ----------

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private string FormatRelativeTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ---------- Render Fragments ----------

    private RenderFragment RenderProfile => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Profile</h4>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                    {
                        <img src="@_editAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <div class="avatar-url-field">
                    <label class="form-label">Avatar URL</label>
                    <input type="url" class="form-control form-control-sm" @bind="_editAvatarUrl" placeholder="https://example.com/avatar.png" />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
            </div>

            <div class="section-actions">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@(!ProfileHasChanges)">
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges" disabled="@(!ProfileHasChanges)">
                    Discard Changes
                </button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Notifications</h4>
            <p class="section-description">Choose how you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <div>
                        <strong>Email Notifications</strong>
                        <div class="text-muted small">Receive notifications via email</div>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_editEmailNotif" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Push Notifications</strong>
                        <div class="text-muted small">Receive push notifications in your browser</div>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_editPushNotif" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Weekly Digest</strong>
                        <div class="text-muted small">Get a weekly summary of activity</div>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_editWeeklyDigest" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <h6 class="mt-4 mb-3">Muted Channels</h6>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@channel</span>
                        @if (isMuted)
                        {
                            <span class="badge bg-secondary ms-auto">Muted</span>
                        }
                    </label>
                }
            </div>

            <div class="section-actions mt-4">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Security</h4>
            <p class="section-description">Manage your account security settings.</p>

            @* Change Password Panel *@
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>🔑 Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary btn-sm" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="toggle-row mt-3">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <div class="small">
                        @if (_securitySettings?.TwoFactorEnabled == true)
                        {
                            <span class="status-badge status-enabled">● Enabled</span>
                        }
                        else
                        {
                            <span class="status-badge status-disabled">● Disabled</span>
                        }
                    </div>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted small mt-2">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                </p>
            }

            @* Active Sessions *@
            <h6 class="mt-4 mb-3">Active Sessions</h6>
            @if (_securitySettings?.Sessions.Count > 0)
            {
                <div class="table-responsive">
                    <table class="table table-sm sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (session.Id == _currentSessionId)
                                        {
                                            <span class="badge bg-success ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatRelativeTime(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _currentSessionId)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => RequestRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">No active sessions.</p>
            }
        </section>
    };

    private RenderFragment RenderAppearance => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Appearance</h4>
            <p class="section-description">Customize how the application looks.</p>

            @* Theme *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-card @(_editTheme == theme ? "selected" : "")">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_editTheme == theme)"
                                   @onchange="() => _editTheme = theme" />
                            <span class="radio-card-icon">
                                @(theme switch { "Light" => "☀️", "Dark" => "🌙", _ => "💻" })
                            </span>
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            @* Font Size *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-card @(_editFontSize == size ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_editFontSize == size)"
                                   @onchange="() => _editFontSize = size" />
                            <span class="radio-card-label" style="font-size: @(size switch { "Small" => "0.8rem", "Large" => "1.3rem", _ => "1rem" })">Aa</span>
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            @* Language *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Language</label>
                <select class="form-select" style="max-width: 300px;"
                        @bind="_editLanguage">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            @* Compact Mode *@
            <div class="toggle-row mb-4">
                <div>
                    <strong>Compact Mode</strong>
                    <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_editCompactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @* Live Preview *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Preview</label>
                <div class="appearance-preview @(_editTheme == "Dark" ? "preview-dark" : "preview-light") @PreviewFontClass @(_editCompactMode ? "preview-compact" : "")">
                    <div class="preview-header">
                        <span class="preview-dot red"></span>
                        <span class="preview-dot yellow"></span>
                        <span class="preview-dot green"></span>
                        <span class="preview-title">Sample Window</span>
                    </div>
                    <div class="preview-body">
                        <div class="preview-sidebar-mock">
                            <div class="mock-nav-item active">Dashboard</div>
                            <div class="mock-nav-item">Settings</div>
                            <div class="mock-nav-item">Profile</div>
                        </div>
                        <div class="preview-content-mock">
                            <h6 class="mb-1">Welcome back!</h6>
                            <p class="mb-2">This is how your content will look with the selected settings.</p>
                            <div class="mock-button">Action</div>
                            <div class="preview-meta mt-2">
                                Theme: @_editTheme · Font: @_editFontSize · Lang: @(_languages.GetValueOrDefault(_editLanguage, _editLanguage))
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div class="section-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

/* Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
    margin: -1rem -1.5rem;
}

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 700;
    color: #333;
    font-size: 1.1rem;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.7rem 1.25rem;
    cursor: pointer;
    color: #555;
    font-weight: 500;
    font-size: 0.95rem;
    transition: all 0.15s ease;
