    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Spanish",
        ["fr"] = "French",
        ["de"] = "German",
        ["ja"] = "Japanese",
        ["zh"] = "Chinese",
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _savedProfile = _profile;
        ResetProfileFields();

        _notificationPrefs = notifTask.Result;
        ResetNotificationFields();

        _securitySettings = securityTask.Result;

        _appearanceSettings = appearanceTask.Result;
        ResetAppearanceFields();
    }

    // ---------- Profile ----------

    private void ResetProfileFields()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editBio = _profile.Bio;
        _editAvatarUrl = _profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _savedProfile = updated;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        _profile = _savedProfile;
        ResetProfileFields();
    }

    private bool ProfileHasChanges =>
        _profile is not null &&
        (_editDisplayName != _savedProfile?.DisplayName ||
         _editEmail != _savedProfile?.Email ||
         _editBio != _savedProfile?.Bio ||
         _editAvatarUrl != _savedProfile?.AvatarUrl);

    // ---------- Notifications ----------

    private void ResetNotificationFields()
    {
        if (_notificationPrefs is null) return;
        _editEmailNotif = _notificationPrefs.EmailNotifications;
        _editPushNotif = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_notificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editEmailNotif, _editPushNotif, _editWeeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        await ShowToast("Notification preferences saved.");
    }

    // ---------- Security ----------

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", isError: true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", isError: true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("Password must be at least 8 characters.", isError: true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // ---------- Appearance ----------

    private void ResetAppearanceFields()
    {
        if (_appearanceSettings is null) return;
        _editTheme = _appearanceSettings.Theme;
        _editFontSize = _appearanceSettings.FontSize;
        _editLanguage = _appearanceSettings.Language;
        _editCompactMode = _appearanceSettings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearanceSettings = updated;
        await ShowToast("Appearance settings saved.");
    }

    private string PreviewFontClass => _editFontSize switch
    {
        "Small" => "preview-font-small",
        "Large" => "preview-font-large",
        _ => "preview-font-medium"
    };

    // ---------- Helpers ----------

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private string FormatRelativeTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ---------- Render Fragments ----------

    private RenderFragment RenderProfile => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Profile</h4>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                    {
                        <img src="@_editAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <div class="avatar-url-field">
                    <label class="form-label">Avatar URL</label>
                    <input type="url" class="form-control form-control-sm" @bind="_editAvatarUrl" placeholder="https://example.com/avatar.png" />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
            </div>

            <div class="section-actions">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@(!ProfileHasChanges)">
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges" disabled="@(!ProfileHasChanges)">
                    Discard Changes
                </button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Notifications</h4>
            <p class="section-description">Choose how you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <div>
                        <strong>Email Notifications</strong>
                        <div class="text-muted small">Receive notifications via email</div>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_editEmailNotif" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Push Notifications</strong>
                        <div class="text-muted small">Receive push notifications in your browser</div>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_editPushNotif" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Weekly Digest</strong>
                        <div class="text-muted small">Get a weekly summary of activity</div>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_editWeeklyDigest" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <h6 class="mt-4 mb-3">Muted Channels</h6>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@channel</span>
                        @if (isMuted)
                        {
                            <span class="badge bg-secondary ms-auto">Muted</span>
                        }
                    </label>
                }
