    private RenderFragment RenderSecurity => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Security</h4>
            <p class="section-description">Manage your account security settings.</p>

            @* Change Password Panel *@
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>🔑 Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary btn-sm" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="toggle-row mt-3">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <div class="small">
                        @if (_securitySettings?.TwoFactorEnabled == true)
                        {
                            <span class="status-badge status-enabled">● Enabled</span>
                        }
                        else
                        {
                            <span class="status-badge status-disabled">● Disabled</span>
                        }
                    </div>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted small mt-2">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                </p>
            }

            @* Active Sessions *@
            <h6 class="mt-4 mb-3">Active Sessions</h6>
            @if (_securitySettings?.Sessions.Count > 0)
            {
                <div class="table-responsive">
                    <table class="table table-sm sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (session.Id == _currentSessionId)
                                        {
                                            <span class="badge bg-success ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatRelativeTime(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _currentSessionId)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => RequestRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">No active sessions.</p>
            }
        </section>
    };

    private RenderFragment RenderAppearance => __builder =>
    {
        <section class="settings-section">
            <h4 class="section-title">Appearance</h4>
            <p class="section-description">Customize how the application looks.</p>

            @* Theme *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-card @(_editTheme == theme ? "selected" : "")">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_editTheme == theme)"
                                   @onchange="() => _editTheme = theme" />
                            <span class="radio-card-icon">
                                @(theme switch { "Light" => "☀️", "Dark" => "🌙", _ => "💻" })
                            </span>
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            @* Font Size *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-card @(_editFontSize == size ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_editFontSize == size)"
                                   @onchange="() => _editFontSize = size" />
                            <span class="radio-card-label" style="font-size: @(size switch { "Small" => "0.8rem", "Large" => "1.3rem", _ => "1rem" })">Aa</span>
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            @* Language *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Language</label>
                <select class="form-select" style="max-width: 300px;"
                        @bind="_editLanguage">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            @* Compact Mode *@
            <div class="toggle-row mb-4">
                <div>
                    <strong>Compact Mode</strong>
                    <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_editCompactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @* Live Preview *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Preview</label>
                <div class="appearance-preview @(_editTheme == "Dark" ? "preview-dark" : "preview-light") @PreviewFontClass @(_editCompactMode ? "preview-compact" : "")">
                    <div class="preview-header">
                        <span class="preview-dot red"></span>
                        <span class="preview-dot yellow"></span>
                        <span class="preview-dot green"></span>
                        <span class="preview-title">Sample Window</span>
                    </div>
                    <div class="preview-body">
                        <div class="preview-sidebar-mock">
                            <div class="mock-nav-item active">Dashboard</div>
                            <div class="mock-nav-item">Settings</div>
                            <div class="mock-nav-item">Profile</div>
                        </div>
                        <div class="preview-content-mock">
                            <h6 class="mb-1">Welcome back!</h6>
                            <p class="mb-2">This is how your content will look with the selected settings.</p>
                            <div class="mock-button">Action</div>
                            <div class="preview-meta mt-2">
                                Theme: @_editTheme · Font: @_editFontSize · Lang: @(_languages.GetValueOrDefault(_editLanguage, _editLanguage))
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div class="section-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

/* Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
    margin: -1rem -1.5rem;
}

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 700;
    color: #333;
    font-size: 1.1rem;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.7rem 1.25rem;
    cursor: pointer;
    color: #555;
    font-weight: 500;
    font-size: 0.95rem;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #333;
}

.settings-nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 800px;
    overflow-y: auto;
}

.settings-section {
    animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}

.section-title {
    font-weight: 700;
    margin-bottom: 0.25rem;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.section-actions {
    display: flex;
    gap: 0.75rem;
    padding-top: 0.5rem;
}

/* Avatar */
.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.25rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    flex-shrink: 0;
    border: 2px solid #dee2e6;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.avatar-url-field {
    flex: 1;
    padding-top: 0.5rem;
}

/* Toggle switch */
.toggle-switch {
    position: relative;
    display: inline-block;
    width: 46px;
    height: 26px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    border-radius: 26px;
    transition: 0.2s;
}

.toggle-slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.2s;
}

.toggle-switch input:checked + .toggle-slider {
    background-color: #0d6efd;
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(20px);
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
    border-bottom: 1px solid #f0f0f0;
}

/* Channel list */
